const repoUrl = $getWorkflowStaticData('global').repo_url || 'https://api.github.com/repos/owner/repo';
const daysBack = $getWorkflowStaticData('global').days_back || 7;
const language = $getWorkflowStaticData('global').language || 'EN';
const deliveryType = $getWorkflowStaticData('global').delivery_type || 'slack';
const webhookUrl = $getWorkflowStaticData('global').webhook_url || '';
const channel = $getWorkflowStaticData('global').channel || '#general';

return [{
  repo_url: repo_url,
  days_back: daysBack,
  language: language,
  delivery_type: deliveryType,
  webhook_url: webhookUrl,
  channel: channel
}];

// Combine commits + issues/PRs into a structured weekly report
const commits = $input.all()[0].json;
const issuesAndPRs = $input.all()[1].json;

const commitList = Array.isArray(commits) ? commits : [commits];
const issueList = Array.isArray(issuesAndPRs) ? issuesAndPRs : [issuesAndPRs];

const formattedCommits = commitList.map(c => ({
  message: c.commit?.message?.split('\n')[0] || c.message || '',
  author: c.author?.login || c.commit?.author?.name || 'Unknown',
  date: c.commit?.author?.date || c.created_at || '',
  sha: c.sha?.substring(0, 7) || ''
}));

const formattedIssues = issueList.filter(i => !i.pull_request).map(i => ({
  title: i.title || '',
  number: i.number || '',
  state: i.state || 'closed',
  author: i.user?.login || 'Unknown',
  url: i.html_url || ''
}));

const formattedPRs = issueList.filter(i => i.pull_request).map(i => ({
  title: i.title || '',
  number: i.number || '',
  state: i.state || 'merged',
  author: i.user?.login || 'Unknown',
  url: i.html_url || ''
}));

return [{
  commits: formattedCommits,
  issues: formattedIssues,
  pull_requests: formattedPRs,
  stats: {
    total_commits: formattedCommits.length,
    total_issues: formattedIssues.length,
    total_prs: formattedPRs.length
  },
  repo: $getWorkflowStaticData('global').repo_url || 'N/A',
  week_start: new Date(Date.now() - 7 * 86400000).toISOString().split('T')[0],
  week_end: new Date().toISOString().split('T')[0]
}];

const data = $input.first().json;
const language = $getWorkflowStaticData('global').language || 'EN';

const promptLang = language === 'ZH' 
  ? `请用中文生成以下GitHub仓库的周报总结。
格式：
## 周报摘要 (data.week_start ~ data.week_end)
### 提交概况
### Issues 动态
### PR 动态
### 亮点与趋势`
  : `Generate a weekly development summary for the following GitHub activity.
Format:
## Weekly Summary (data.week_start ~ data.week_end)
### Commit Overview
### Issues Activity
### PR Activity
### Highlights & Trends`;

const prompt = promptLang + `

Repository: ${data.repo}
Period: ${data.week_start} to ${data.week_end}

Commits:${JSON.stringify(data.commits.slice(0, 30))}

Closed Issues:${JSON.stringify(data.issues.slice(0, 20))}

Merged PRs:${JSON.stringify(data.pull_requests.slice(0, 20))}

Stats: ${data.stats.total_commits} commits, ${data.stats.total_issues} issues closed, ${data.stats.total_prs} PRs merged.

Generate a concise, well-structured narrative summary highlighting key changes, patterns, and notable events from this week's development activity.`;

return [{ prompt: prompt }];

const response = $input.first().json;
let summary = response.content?.[0]?.text || response.content || JSON.stringify(response);

const data = $input.first().json;

return [{
  summary: summary,
  stats: data.stats,
  repo: data.repo,
  week_start: data.week_start,
  week_end: data.week_end,
  generated_at: new Date().toISOString()
}];

const { summary, repo, week_start, week_end, stats } = $input.first().json;
const deliveryType = $getWorkflowStaticData('global').delivery_type || 'slack';
const webhookUrl = $getWorkflowStaticData('global').webhook_url || '';
const channel = $getWorkflowStaticData('global').channel || '#general';

const message = `📊 *Weekly Dev Report*\n📅 ${week_start} ~ ${week_end}\n📦 ${repo}\n\n📈 Stats: ${stats.total_commits} commits | ${stats.total_issues} issues | ${stats.total_prs} PRs\n\n${summary}`;

if (deliveryType === 'slack' && webhookUrl) {
  return [{
    webhook_url: webhookUrl,
    message: JSON.stringify({ text: message, channel: channel }),
    headers: { 'Content-Type': 'application/json' }
  }];
} else if (deliveryType === 'discord' && webhookUrl) {
  return [{
    webhook_url: webhookUrl,
    message: JSON.stringify({ content: message }),
    headers: { 'Content-Type': 'application/json' }
  }];
}

// Default: output to console
return [{ message: message }];
